    .insert(chatThreads)
    .values({
      id: threadId,
      workspaceId,
      title: question.slice(0, 80),
      updatedAt: new Date(),
    })
    .onConflictDoUpdate({
      target: chatThreads.id,
      set: { updatedAt: new Date() },
    });

