const fs = require('node:fs');
const path = require('node:path');
const root = '/Users/socrates/Documents/syntheci-shipping/demo-data';
const emails = JSON.parse(fs.readFileSync(path.join(root, 'emails/emails.json'), 'utf8'));
const emailIds = new Set(emails.map((email) => email.email_id));
const docFiles = fs.readdirSync(path.join(root, 'documents')).filter((file) => file.endsWith('.md'));
const docIds = new Map();
const errors = [];
for (const file of docFiles) {
  const source = fs.readFileSync(path.join(root, 'documents', file), 'utf8');
  const match = source.match(/^---\n([\s\S]*?)\n---/);
  if (!match) errors.push(`${file}: missing front matter`);
  const fields = Object.fromEntries((match?.[1] ?? '').split('\n').filter(Boolean).map((line) => {
    const index = line.indexOf(':');
    return [line.slice(0, index).trim(), line.slice(index + 1).trim()];
  }));
  if (!fields.document_id) errors.push(`${file}: missing document_id`);
  if (docIds.has(fields.document_id)) errors.push(`${file}: duplicate document_id ${fields.document_id}`);
  docIds.set(fields.document_id, file);
  if (!emailIds.has(fields.source_email_id)) errors.push(`${file}: source email missing ${fields.source_email_id}`);
}
for (const email of emails) {
  for (const attachment of email.attachments ?? []) {
    if (!docIds.has(attachment.document_id)) errors.push(`${email.email_id}: attachment doc missing ${attachment.document_id}`);
    const expected = attachment.path?.replace('demo-data/documents/', '');
    if (expected && !fs.existsSync(path.join(root, 'documents', expected))) errors.push(`${email.email_id}: path missing ${attachment.path}`);
  }
}
if (errors.length) {
  console.error(errors.join('\n'));
  process.exit(1);
}
console.log(`checked ${emails.length} emails and ${docFiles.length} documents`);
